 89→// CapturePrePromptState captures current untracked files and transcript position before a prompt
 90→// and saves them to a state file.
 91→//
 92→// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
 93→// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
 94→// The sessionRef parameter is optional — if empty, transcript position won't be captured.
 95→//
 96→// Works correctly from any subdirectory within the repository.
 97→func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
 98→	if sessionID == "" {
 99→		sessionID = unknownSessionID
100→	}
101→
102→	if err := validation.ValidateSessionID(sessionID); err != nil {
103→		return fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
104→	}
105→
106→	// Get absolute path for tmp directory
107→	tmpDirAbs := resolveTmpDir(ctx)
108→
109→	// Create tmp directory if it doesn't exist
110→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
111→		return fmt.Errorf("failed to create tmp directory: %w", err)
112→	}
113→
114→	// Get list of untracked files (excluding .entire directory itself)
115→	untrackedFiles, err := getUntrackedFilesForState(ctx)
116→	if err != nil {
117→		return fmt.Errorf("failed to get untracked files: %w", err)
118→	}
119→
120→	// Get transcript position using TranscriptAnalyzer if available
121→	var transcriptOffset int
122→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok && sessionRef != "" {
123→		pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
124→		if posErr != nil {
125→			logging.Warn(logging.WithComponent(ctx, "state"), "failed to get transcript position",
126→				slog.String("error", posErr.Error()))
127→		} else {
128→			transcriptOffset = pos
129→		}
130→	}
131→
132→	// Create state file using os.Root for traversal-resistant write
133→	state := PrePromptState{
134→		SessionID:        sessionID,
135→		Timestamp:        time.Now().UTC().Format(time.RFC3339),
136→		UntrackedFiles:   untrackedFiles,
137→		TranscriptOffset: transcriptOffset,
138→	}
139→
140→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
141→	if err != nil {
142→		return fmt.Errorf("failed to marshal state: %w", err)
143→	}
144→
145→	fileName := fmt.Sprintf("pre-prompt-%s.json", sessionID)
146→	root, err := os.OpenRoot(tmpDirAbs)
147→	if err != nil {
148→		return fmt.Errorf("failed to open tmp directory root: %w", err)
149→	}
150→	defer root.Close()
151→
152→	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
153→		return fmt.Errorf("failed to write state file: %w", err)
154→	}
155→
156→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before prompt",
157→		slog.Int("untracked_files", len(untrackedFiles)),
158→		slog.Int("transcript_offset", transcriptOffset))
159→	return nil
160→}
