162→// LoadPrePromptState loads previously captured state.
163→// Returns nil if no state file exists.
164→func LoadPrePromptState(ctx context.Context, sessionID string) (*PrePromptState, error) {
165→	if err := validation.ValidateSessionID(sessionID); err != nil {
166→		return nil, fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
167→	}
168→
169→	tmpDirAbs := resolveTmpDir(ctx)
170→
171→	root, err := os.OpenRoot(tmpDirAbs)
172→	if err != nil {
173→		// Directory doesn't exist yet — no state file
174→		if os.IsNotExist(err) {
175→			return nil, nil //nolint:nilnil // already present in codebase
176→		}
177→		return nil, fmt.Errorf("failed to open tmp directory root: %w", err)
178→	}
179→	defer root.Close()
180→
181→	fileName := fmt.Sprintf("pre-prompt-%s.json", sessionID)
182→	data, err := osroot.ReadFile(root, fileName)
183→	if err != nil {
184→		if os.IsNotExist(err) {
185→			return nil, nil //nolint:nilnil // already present in codebase
186→		}
187→		return nil, fmt.Errorf("failed to read state file: %w", err)
188→	}
189→
190→	var state PrePromptState
191→	if err := json.Unmarshal(data, &state); err != nil {
192→		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
193→	}
194→
195→	state.normalizePrePromptState()
196→
197→	return &state, nil
198→}
