557→// preTaskFilePrefix is the prefix for pre-task state files
558→const preTaskFilePrefix = "pre-task-"
559→
560→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
561→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
562→// When multiple pre-task files exist (nested subagents), returns the most recently
563→// modified one.
564→// Works correctly from any subdirectory within the repository.
565→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
566→	tmpDirAbs := resolveTmpDir(ctx)
567→	entries, err := os.ReadDir(tmpDirAbs)
568→	if err != nil {
569→		return "", false
570→	}
571→
572→	var latestFile string
573→	var latestTime time.Time
574→
575→	for _, entry := range entries {
576→		if entry.IsDir() {
577→			continue
578→		}
579→		name := entry.Name()
580→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
581→			continue
582→		}
583→
584→		// Check modification time for nested subagent handling
585→		info, err := entry.Info()
586→		if err != nil {
587→			continue
588→		}
589→		if latestFile == "" || info.ModTime().After(latestTime) {
590→			latestFile = name
591→			latestTime = info.ModTime()
592→		}
593→	}
594→
595→	if latestFile == "" {
596→		return "", false
597→	}
598→
599→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
600→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
601→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
602→	return toolUseID, true
603→}
