 47→// copyFile copies a file from src to dst using os.Root for traversal-resistant
 48→// writes (Go 1.24+). dst must be absolute and reside under either the repo
 49→// worktree root, the user's home directory (for agent session dirs such as
 50→// ~/.claude/), or the system temp directory (used during tests).
 51→// The kernel enforces that the write cannot escape the allowed directory,
 52→// eliminating TOCTOU races and symlink escapes.
 53→func copyFile(src, dst string) error {
 54→	src = filepath.Clean(src)
 55→	dst = filepath.Clean(dst)
 56→
 57→	if !filepath.IsAbs(dst) {
 58→		return fmt.Errorf("copyFile: dst must be absolute, got %q", dst)
 59→	}
 60→
 61→	input, err := os.ReadFile(src)
 62→	if err != nil {
 63→		return err //nolint:wrapcheck // already present in codebase
 64→	}
 65→
 66→	root, relPath, err := openAllowedRoot(dst)
 67→	if err != nil {
 68→		return err
 69→	}
 70→	defer root.Close()
 71→
 72→	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
 73→		return fmt.Errorf("failed to write file: %w", err)
 74→	}
 75→	return nil
 76→}
 77→
 78→// openAllowedRoot finds the allowed root directory that contains dst and returns
 79→// an os.Root handle along with the relative path within that root.
 80→// Allowed directories: repo worktree root, user home, system temp dir.
 81→// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
 82→func openAllowedRoot(dst string) (*os.Root, string, error) {
 83→	allowed := allowedRootDirs()
 84→
 85→	// Resolve the directory portion of dst through symlinks so that e.g.
 86→	// /var/folders/... matches /private/var/folders/... on macOS.
 87→	// Only the parent directory is resolved; the final component may not exist yet.
 88→	resolvedDst := dst
 89→	if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
 90→		resolvedDst = filepath.Join(r, filepath.Base(dst))
 91→	}
 92→
 93→	for _, dir := range allowed {
 94→		rel, err := filepath.Rel(dir, resolvedDst)
 95→		if err != nil {
 96→			continue
 97→		}
 98→		// Check that rel doesn't escape dir (traversal-resistant).
 99→		// This is the same logic as paths.IsSubpath but avoids a redundant
100→		// filepath.Rel call since we already have rel.
101→		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
102→			continue
103→		}
104→		root, err := os.OpenRoot(dir)
105→		if err != nil {
106→			return nil, "", fmt.Errorf("copyFile: failed to open root %q: %w", dir, err)
107→		}
108→		return root, rel, nil
109→	}
110→
111→	return nil, "", fmt.Errorf("copyFile: dst %q is outside allowed directories", dst)
112→}
113→
114→// allowedRootDirs returns the list of directories that copyFile may write to.
115→// Directories are resolved through symlinks so they match resolved dst paths.
116→func allowedRootDirs() []string {
117→	allowed := make([]string, 0, 3)
118→
119→	if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
120→		allowed = appendResolved(allowed, repoRoot)
121→	}
122→	if home, err := os.UserHomeDir(); err == nil {
123→		allowed = appendResolved(allowed, home)
124→	}
125→	if tmpDir := os.TempDir(); tmpDir != "" {
126→		allowed = appendResolved(allowed, tmpDir)
127→	}
128→
129→	return allowed
130→}
131→
132→// appendResolved appends dir to the list after resolving symlinks.
133→// Falls back to the original path if symlink resolution fails.
134→func appendResolved(dirs []string, dir string) []string {
135→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
136→		return append(dirs, resolved)
137→	}
138→	return append(dirs, dir)
139→}
