184→func TestFilterAndNormalizePaths_SiblingDirectories(t *testing.T) {
185→	// This test verifies the fix for the bug where files in sibling directories
186→	// were filtered out when Claude runs from a subdirectory.
187→	// When Claude is in /repo/frontend and edits /repo/api/file.ts,
188→	// the relative path would be ../api/file.ts which was incorrectly filtered.
189→	// The fix uses repo root instead of cwd, so paths should be api/file.ts.
190→
191→	tests := []struct {
192→		name     string
193→		files    []string
194→		basePath string // simulates repo root or cwd
195→		want     []string
196→	}{
197→		{
198→			name: "files in sibling directories with repo root base",
199→			files: []string{
200→				"/repo/api/src/lib/github.ts",
201→				"/repo/api/src/types.ts",
202→				"/repo/frontend/src/pages/api.ts",
203→			},
204→			basePath: "/repo", // repo root
205→			want: []string{
206→				"api/src/lib/github.ts",
207→				"api/src/types.ts",
208→				"frontend/src/pages/api.ts",
209→			},
210→		},
211→		{
212→			name: "files in sibling directories with subdirectory base (old buggy behavior)",
213→			files: []string{
214→				"/repo/api/src/lib/github.ts",
215→				"/repo/frontend/src/pages/api.ts",
216→			},
217→			basePath: "/repo/frontend", // cwd in subdirectory
218→			want: []string{
219→				// Only frontend file should remain, api file gets filtered
220→				// because ../api/... starts with ..
221→				"src/pages/api.ts",
222→			},
223→		},
224→		{
225→			name: "relative paths pass through unchanged",
226→			files: []string{
227→				"src/file.ts",
228→				"lib/util.go",
229→			},
230→			basePath: "/repo",
231→			want: []string{
232→				"src/file.ts",
233→				"lib/util.go",
234→			},
235→		},
236→		{
237→			name: "infrastructure paths are filtered",
238→			files: []string{
239→				"/repo/src/file.ts",
240→				"/repo/.entire/metadata/session.json",
241→			},
242→			basePath: "/repo",
243→			want: []string{
244→				"src/file.ts",
245→				// .entire path should be filtered
246→			},
247→		},
248→	}
249→
250→	for _, tt := range tests {
251→		t.Run(tt.name, func(t *testing.T) {
252→			got := FilterAndNormalizePaths(tt.files, tt.basePath)
253→			if len(got) != len(tt.want) {
254→				t.Errorf("FilterAndNormalizePaths() returned %d files, want %d\ngot: %v\nwant: %v",
255→					len(got), len(tt.want), got, tt.want)
256→				return
257→			}
258→			for i, want := range tt.want {
259→				if got[i] != want {
260→					t.Errorf("FilterAndNormalizePaths()[%d] = %v, want %v", i, got[i], want)
261→				}
262→			}
263→		})
264→	}
265→}
